"use client";

import React from "react";
import { Code2, Copy, Check } from "lucide-react";
import { EventPlan } from "@/types/event";

interface RawJsonViewerProps {
  plan: EventPlan;
  isCopied: boolean;
  onCopy: () => void;
}

/**
 * Technical inspection view rendering the raw, schema-compliant JSON blueprint
 * generated by Gemini 3.8 Flash.
 */
export default function RawJsonViewer({
  plan,
  isCopied,
  onCopy,
}: RawJsonViewerProps) {
  return (
    <section aria-label="Raw JSON Blueprint" className="glass-panel rounded-2xl p-6 space-y-4 border border-white/10">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h3 className="text-base font-bold text-white flex items-center space-x-2">
            <Code2 className="w-4 h-4 text-fuchsia-400" aria-hidden="true" />
            <span>Raw Master JSON Blueprint (Gemini 3.8 Flash)</span>
          </h3>
          <p className="text-xs text-slate-300 mt-0.5">
            Strict adherence to Challenge 5 celebration schema specifications
          </p>
        </div>

        <button
          type="button"
          onClick={onCopy}
          aria-label="Copy raw JSON blueprint to clipboard"
          className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-white/10 hover:bg-white/20 text-white flex items-center space-x-1.5 transition-all self-start sm:self-auto focus-visible:outline-2 focus-visible:outline-fuchsia-400"
        >
          {isCopied ? (
            <>
              <Check className="w-3.5 h-3.5 text-emerald-400" aria-hidden="true" />
              <span>Copied</span>
            </>
          ) : (
            <>
              <Copy className="w-3.5 h-3.5 text-slate-300" aria-hidden="true" />
              <span>Copy JSON</span>
            </>
          )}
        </button>
      </div>

      <div className="bg-slate-950 p-4 rounded-xl border border-white/10 overflow-x-auto max-h-[550px] font-mono text-xs text-emerald-400 leading-relaxed shadow-inner">
        <pre>{JSON.stringify(plan, null, 2)}</pre>
      </div>
    </section>
  );
}

